import { useState, useMemo, type FormEvent } from 'react';
import { Plus, Edit2, Trash2, Search, RefreshCw, Loader2, Upload, Circle, Pencil, Image as ImageIcon, RotateCcw } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Input } from '@/components/ui/input';
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from '@/components/ui/alert-dialog';
import I18nInput from '@/components/I18nInput';
import { useFeatures, type IFeature } from '@/hooks/useFeatures';
import { createI18nText, type I18nText } from '@/lib/i18n-text';
import { batchTranslateI18n } from '@/lib/translate';
import { toast } from 'sonner';
import * as Icons from 'lucide-react';
import { useI18n } from '@/i18n/I18nContext';
import PageBreadcrumb from '@/components/PageBreadcrumb';
import { useSyncService } from '@/context/SyncServiceContext';
import SyncStatusBadge from '@/components/SyncStatusBadge';
import { imgPath } from '@/utils/img-path';
import { Image } from '@/components/ui/image';
import { compressImage } from '@/lib/image-compress';

const ICON_OPTIONS = [
  'Factory',
  'ShieldCheck',
  'Globe',
  'Clock',
  'Headphones',
  'Settings',
  'Lightbulb',
  'Layers',
  'Shield',
  'Gauge',
  'Hammer',
  'Box',
];

function getIcon(name: string) {
  const IconComp = (Icons as unknown as Record<string, React.ComponentType<{ className?: string }>>)[name];
  return IconComp || Circle;
}

interface FormState {
  title: I18nText;
  description: I18nText;
  icon: string;
  order: string;
}

const INITIAL_FORM: FormState = {
  title: createI18nText(''),
  description: createI18nText(''),
  icon: 'Factory',
  order: '1',
};

export default function AdminFeaturesPage() {
  const { adminT } = useI18n();
  const { features, sectionImage, loading, addFeature, updateFeature, deleteFeature, setFeatureSectionImage, resetFeatureSectionImage } = useFeatures();
  const { markDirty, syncModule, syncJsonFile, syncImagesInData, getStatus } = useSyncService();
  const syncStatus = getStatus('features');
  const [dialogOpen, setDialogOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [form, setForm] = useState<FormState>(INITIAL_FORM);
  const [keyword, setKeyword] = useState('');
  const [deleteId, setDeleteId] = useState<string | null>(null);
  const [dialogTranslating, setDialogTranslating] = useState(false);
  const [dialogProgress, setDialogProgress] = useState({ current: 0, total: 0 });
  const [pageTranslating, setPageTranslating] = useState(false);
  const [pageProgress, setPageProgress] = useState({ current: 0, total: 0 });

  const filtered = useMemo(() => {
    return features.filter(
      (f) =>
        f.title.en.toLowerCase().includes(keyword.toLowerCase()) ||
        f.description.en.toLowerCase().includes(keyword.toLowerCase())
    );
  }, [features, keyword]);

  const openAdd = () => {
    setEditingId(null);
    const nextOrder = features.length > 0 ? Math.max(...features.map((f) => f.order)) + 1 : 1;
    setForm({ ...INITIAL_FORM, order: String(nextOrder) });
    setDialogOpen(true);
  };

  const openEdit = (feat: IFeature) => {
    setEditingId(feat.id);
    setForm({
      title: feat.title,
      description: feat.description,
      icon: feat.icon,
      order: String(feat.order),
    });
    setDialogOpen(true);
  };

  const handleTranslateAll = async () => {
    const tasks = [
      { label: adminT('admin.title'), value: form.title },
      { label: adminT('admin.description'), value: form.description },
    ].filter((t) => t.value.en.trim());
    if (!tasks.length) {
      toast.error('Please enter English text first');
      return;
    }
    setDialogTranslating(true);
    setDialogProgress({ current: 0, total: tasks.length });
    try {
      const results = await batchTranslateI18n(tasks, (cur, total) => {
        setDialogProgress({ current: cur, total });
      });
      const newForm = { ...form };
      const formDict = newForm as unknown as Record<string, I18nText>;
      for (let i = 0; i < results.length; i++) {
        const task = tasks[i];
        if (task && formDict[task.label]) {
          formDict[task.label] = results[i].value;
        }
      }
      setForm(newForm);
      const successCount = results.filter((r) => r.success).length;
      const failed = results.filter((r) => !r.success && !r.skipped);
      if (failed.length > 0) {
        toast.warning(`Translated ${successCount}/${results.length}. Failed: ${failed.map((f) => f.label).join(', ')}`);
      } else {
        toast.success('Translated to all languages');
      }
    } catch {
      toast.error('Translation failed. Please try again.');
    } finally {
      setDialogTranslating(false);
      setDialogProgress({ current: 0, total: 0 });
    }
  };

  const handlePageTranslateAll = async () => {
    if (features.length === 0) {
      toast.warning('No features to translate');
      return;
    }
    const fieldNames: Array<'title' | 'description'> = ['title', 'description'];
    const tasks = features.flatMap((f) =>
      fieldNames.map((fn) => ({
        label: `${f.title.en.slice(0, 20)} / ${fn}`,
        value: f[fn],
      })),
    ).filter((t) => t.value.en.trim());

    if (tasks.length === 0) {
      toast.warning('No English content found to translate');
      return;
    }

    setPageTranslating(true);
    setPageProgress({ current: 0, total: tasks.length });
    try {
      const results = await batchTranslateI18n(tasks, (cur, total) => {
        setPageProgress({ current: cur, total });
      });

      let resultIdx = 0;
      for (const feat of features) {
        const updates: Partial<IFeature> = {};
        let changed = false;
        for (const f of fieldNames) {
          if (feat[f].en.trim()) {
            const r = results[resultIdx];
            if (r && !r.skipped && r.success) {
              updates[f] = r.value;
              changed = true;
            }
            resultIdx++;
          }
        }
        if (changed) {
          updateFeature(feat.id, { ...feat, ...updates });
          markDirty('features');
        }
      }

      const successCount = results.filter((r) => r.success).length;
      const failed = results.filter((r) => !r.success && !r.skipped);
      if (failed.length > 0) {
        toast.warning(`Translated ${successCount}/${results.length}. ${failed.length} failed.`);
      } else {
        toast.success(`Translation completed: ${successCount} fields translated`);
      }
    } catch {
      toast.error('Translation failed. Please try again.');
    } finally {
      setPageTranslating(false);
      setPageProgress({ current: 0, total: 0 });
    }
  };

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();
    if (!form.title.en.trim()) {
      toast.error('English title is required');
      return;
    }
    const orderNum = parseInt(form.order, 10) || 1;
    if (editingId) {
      updateFeature(editingId, {
        title: form.title,
        description: form.description,
        icon: form.icon,
        order: orderNum,
      });
      markDirty('features');
      toast.success(adminT('admin.featureUpdated'));
    } else {
      addFeature({
        title: form.title,
        description: form.description,
        icon: form.icon,
        order: orderNum,
      });
      markDirty('features');
      toast.success('Feature added');
    }
    setDialogOpen(false);
  };

  const handleDelete = () => {
    if (!deleteId) return;
    deleteFeature(deleteId);
    setDeleteId(null);
    markDirty('features');
    toast.success(adminT('admin.featureDeleted'));
  };

  const handleSectionImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    if (!file.type.startsWith('image/')) {
      toast.error('Please upload a valid image file');
      return;
    }
    if (file.size > 5 * 1024 * 1024) {
      toast.error('Image size must be under 5MB');
      return;
    }
    try {
      const compressed = await compressImage(file, { maxWidth: 1600, maxHeight: 900, quality: 0.78 });
      const ok = setFeatureSectionImage(compressed);
      if (ok) {
        toast.success('Section image uploaded');
        markDirty('features');
      } else {
        toast.error('Failed to save image');
      }
    } catch (err) {
      toast.error('Failed to process image: ' + (err instanceof Error ? err.message : String(err)));
    }
    e.target.value = '';
  };

  const handleSectionImageReset = () => {
    const ok = resetFeatureSectionImage();
    if (ok) {
      toast.success('Section image restored to default');
      markDirty('features');
    }
    else toast.error('Failed to reset image');
  };

  const previewSrc = sectionImage || imgPath('/images/factory-2.jpg');

  if (loading) {
    return (
      <div className="flex items-center justify-center py-20">
        <div className="w-8 h-8 border-2 border-primary border-t-transparent rounded-full animate-spin" />
      </div>
    );
  }

  return (
    <div className="space-y-4">
      {/* Breadcrumb */}
      <PageBreadcrumb
        firstItem={{ label: adminT('admin.dashboard'), href: '/admin/dashboard', icon: 'dashboard' }}
        items={[
          { label: adminT('admin.features') },
        ]}
      />

      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-foreground">Why Choose Us / Features</h1>
          <p className="text-sm text-muted-foreground mt-1">
            {features.length} features displayed on homepage
          </p>
        </div>
        <div className="flex items-center gap-2">
          <SyncStatusBadge status={syncStatus} />
          <Button
            variant="outline"
            size="sm"
            onClick={() =>
              syncModule('features', 'Features', async (config) => {
                const dataWithImages = await syncImagesInData(
                  config,
                  features,
                  'features',
                  []
                );
                // Also sync section image if it's a custom base64
                let sectionImg = sectionImage;
                if (sectionImg && sectionImg.startsWith('data:image/')) {
                  const { generateImageFilename } = await import('@/hooks/useGithubSync');
                  const targetPath = generateImageFilename('section-image.jpg', 'features');
                  const { syncBase64Image } = useSyncService as any;
                  // Use direct sync
                  const { createOrUpdateFile } = await import('@/lib/github-api');
                  const { extractBase64FromDataUrl } = await import('@/hooks/useGithubSync');
                  const { base64 } = extractBase64FromDataUrl(sectionImg);
                  await createOrUpdateFile(config, targetPath, base64, `Upload ${targetPath}`, true);
                  sectionImg = `/${targetPath}`;
                }
                await syncJsonFile(
                  config,
                  'data/features.json',
                  { data: dataWithImages, sectionImage: sectionImg },
                  'Update features data'
                );
              })
            }
            disabled={syncStatus === 'syncing'}
            className="text-xs h-9"
          >
            <Upload className="size-3.5 mr-1.5" />
            Sync to GitHub
          </Button>
          <div className="relative">
            <Search className="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" />
            <Input
              value={keyword}
              onChange={(e) => setKeyword(e.target.value)}
              placeholder="Search features..."
              className="w-56 pl-9"
            />
          </div>
          <Button
            variant="outline"
            size="sm"
            onClick={handlePageTranslateAll}
            disabled={pageTranslating || features.length === 0}
            className="text-xs h-9"
          >
            {pageTranslating ? (
              <>
                <Loader2 className="size-3.5 mr-1.5 animate-spin" />
                Translating {pageProgress.current}/{pageProgress.total}...
              </>
            ) : (
              <>
                <RefreshCw className="size-3.5 mr-1.5" />
                Translate All
              </>
            )}
          </Button>
          <Button onClick={openAdd} className="bg-primary hover:bg-primary/90 text-primary-foreground">
            <Plus className="size-4 mr-2" />
            Add Feature
          </Button>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Left: Features list */}
        <div className="lg:col-span-2">
          <Card>
            <CardHeader className="pb-3">
              <CardTitle className="text-base">All Features</CardTitle>
            </CardHeader>
            <CardContent className="p-0">
              <div className="w-full overflow-x-auto">
                <table className="w-full text-sm">
                  <thead>
                    <tr className="border-b border-border">
                      <th className="text-left font-medium text-muted-foreground px-4 py-3 w-12"></th>
                      <th className="text-left font-medium text-muted-foreground px-4 py-3">{adminT('admin.nameEn')}</th>
                      <th className="text-left font-medium text-muted-foreground px-4 py-3">{adminT('admin.descriptionEn')}</th>
                      <th className="text-left font-medium text-muted-foreground px-4 py-3 w-20">{adminT('admin.sortOrder')}</th>
                      <th className="text-right font-medium text-muted-foreground px-4 py-3">{adminT('admin.actions')}</th>
                    </tr>
                  </thead>
                  <tbody>
                {filtered.length === 0 ? (
                  <tr>
                    <td colSpan={5} className="text-center text-muted-foreground py-12">
                      No features found
                    </td>
                  </tr>
                ) : (
                  filtered.map((feat) => {
                    const IconComp = getIcon(feat.icon);
                    return (
                      <tr key={feat.id} className="border-b border-border/50 hover:bg-muted/20 transition-colors">
                        <td className="px-4 py-3">
                          <div className="w-9 h-9 rounded-md bg-primary/10 flex items-center justify-center">
                            <IconComp className="size-4 text-primary" />
                          </div>
                        </td>
                        <td className="px-4 py-3 font-medium">{feat.title.en}</td>
                        <td className="px-4 py-3 text-muted-foreground max-w-md">
                          <span className="line-clamp-1 block">{feat.description.en}</span>
                        </td>
                        <td className="px-4 py-3 text-muted-foreground tabular-nums">{feat.order}</td>
                        <td className="px-4 py-3">
                          <div className="flex items-center justify-end gap-1">
                            <Button
                              variant="ghost"
                              size="icon"
                              onClick={() => openEdit(feat)}
                              className="h-8 w-8"
                            >
                              <Pencil className="size-3.5" />
                            </Button>
                            <AlertDialog open={deleteId === feat.id} onOpenChange={(open) => !open && setDeleteId(null)}>
                              <AlertDialogTrigger asChild>
                                <Button
                                  variant="ghost"
                                  size="icon"
                                  onClick={() => setDeleteId(feat.id)}
                                  className="h-8 w-8 text-destructive hover:text-destructive hover:bg-destructive/10"
                                >
                                  <Trash2 className="size-3.5" />
                                </Button>
                              </AlertDialogTrigger>
                              <AlertDialogContent>
                                <AlertDialogHeader>
                                  <AlertDialogTitle>Delete Feature?</AlertDialogTitle>
                                  <AlertDialogDescription>
                                    This action cannot be undone. The feature will be removed from the homepage.
                                  </AlertDialogDescription>
                                </AlertDialogHeader>
                                <AlertDialogFooter>
                                  <AlertDialogCancel>{adminT('admin.cancel')}</AlertDialogCancel>
                                  <AlertDialogAction
                                    onClick={handleDelete}
                                    className="bg-destructive hover:bg-destructive/90"
                                  >
                                    Delete
                                  </AlertDialogAction>
                                </AlertDialogFooter>
                              </AlertDialogContent>
                            </AlertDialog>
                          </div>
                        </td>
                      </tr>
                    );
                  })
                )}
                   </tbody>
                 </table>
               </div>
             </CardContent>
           </Card>
         </div>

         {/* Right: Section Image Upload */}
         <div>
           <Card>
             <CardHeader className="pb-3">
               <CardTitle className="text-base flex items-center gap-2">
                 <ImageIcon className="size-4 text-primary" />
                 Section Image
               </CardTitle>
             </CardHeader>
             <CardContent className="space-y-4">
               <div className="relative w-full aspect-[4/5] rounded-md overflow-hidden border border-border bg-card">
                 <Image
                   src={previewSrc}
                   alt="Features section preview"
                   className="w-full h-full object-cover"
                 />
                 <div className="absolute bottom-2 left-2 right-2">
                   <span className="text-xs px-2 py-1 rounded bg-black/60 text-white/90">
                     {sectionImage ? 'Custom Image' : 'Default Image'}
                   </span>
                 </div>
               </div>
               <div className="space-y-3">
                 <div>
                   <label className="text-sm font-medium">Upload Image</label>
                   <div className="mt-2">
                     <label
                       htmlFor="features-section-img-upload"
                       className="inline-flex items-center gap-2 px-4 py-2 rounded-sm border border-border bg-background hover:bg-accent hover:text-accent-foreground cursor-pointer transition-colors text-sm w-full justify-center"
                     >
                       <Upload className="size-4" />
                       Choose Image
                     </label>
                     <input
                       id="features-section-img-upload"
                       type="file"
                       accept="image/*"
                       onChange={handleSectionImageUpload}
                       className="hidden"
                     />
                     <p className="text-xs text-muted-foreground mt-2">
                       Any image format, max 5MB
                     </p>
                   </div>
                 </div>
                 <div>
                   <Button
                     type="button"
                     size="sm"
                     variant="outline"
                     onClick={handleSectionImageReset}
                     disabled={!sectionImage}
                     className="w-full"
                   >
                     <RotateCcw className="size-4 mr-2" />
                     Restore Default
                   </Button>
                 </div>
                 <p className="text-xs text-muted-foreground">
                   This image appears on the homepage next to the "Why Choose Us" features list.
                 </p>
               </div>
             </CardContent>
           </Card>
         </div>
       </div>

       {/* Dialog */}
      <Dialog open={dialogOpen} onOpenChange={setDialogOpen}>
        <DialogContent className="max-w-xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle className="flex items-center justify-between flex-wrap gap-2">
              <span>{editingId ? adminT('admin.editFeature') : adminT('admin.addFeature')}</span>
              <Button
                type="button"
                size="sm"
                variant="outline"
                onClick={handleTranslateAll}
                disabled={dialogTranslating}
                className="text-xs h-8"
              >
                {dialogTranslating ? (
                  <>
                    <Loader2 className="size-3.5 mr-1.5 animate-spin" />
                    Translating {dialogProgress.current}/{dialogProgress.total}...
                  </>
                ) : (
                  <>
                    <RefreshCw className="size-3 mr-1.5" /> Translate All
                  </>
                )}
              </Button>
            </DialogTitle>
          </DialogHeader>
          <form onSubmit={handleSubmit} className="space-y-4">
            <I18nInput
              label="Title"
              value={form.title}
              onChange={(v) => setForm({ ...form, title: v })}
              placeholder="Fast Delivery"
              
            />
            <I18nInput
              label="Description"
              value={form.description}
              onChange={(v) => setForm({ ...form, description: v })}
              placeholder="Brief description..."
              multiline
              rows={3}
              
            />
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <label className="text-sm font-medium">{adminT('admin.icon')}</label>
                <Select value={form.icon} onValueChange={(v) => setForm({ ...form, icon: v })}>
                  <SelectTrigger>
                    <SelectValue placeholder="Select an icon" />
                  </SelectTrigger>
                  <SelectContent>
                    {ICON_OPTIONS.map((name) => {
                      const IconComp = getIcon(name);
                      return (
                        <SelectItem key={name} value={name}>
                          <div className="flex items-center gap-2">
                            <IconComp className="size-4" />
                            {name}
                          </div>
                        </SelectItem>
                      );
                    })}
                  </SelectContent>
                </Select>
              </div>
              <div className="space-y-2">
                <label className="text-sm font-medium">{adminT('admin.sortOrder')}</label>
                <Input
                  type="number"
                  value={form.order}
                  onChange={(e) => setForm({ ...form, order: e.target.value })}
                  min={1}
                />
              </div>
            </div>
            <DialogFooter className="pt-2">
              <Button type="button" variant="outline" onClick={() => setDialogOpen(false)}>
                Cancel
              </Button>
              <Button type="submit" className="bg-primary hover:bg-primary/90">
                {editingId ? adminT('admin.edit') : adminT('admin.addFeature')}
              </Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>
    </div>
  );
}
